    "guide.pair.code" to "ウォッチで：「接続」→「ペアリングコードを生成」、次にその6桁のコードをここに入力します：",
    "guide.pair.relinkTitle" to "切り替えまたは切断（Garmin）：",
    "guide.pair.relink" to "「連携アカウント」でウォッチを切断すると、次にサーバーに到達したときにウォッチ自身がペアリングを解除します — 「接続済み」の代わりに再びコードを表示します。既存のペアリングを上書きするには（別のウォッチ／アカウント）：ウォッチで「接続」→ ENTER でいつでも新しいコードを生成できます。ここで新しいコードを引き換えるまで古いトークンは有効なままなので、中断した試行は何も変えません。",
    "guide.pair.note" to "メール、Google、または Apple でサインイン — 同じメールなら同じアカウントで、別途連携は不要です。",
    "guide.connect" to "「接続」",
    "guide.garminSub" to "Fenix、Forerunner、Epix、Instinct …",
    "guide.g.storeLead" to "ストアで公開中 — 直接インストールするのが一番簡単です：",
    "guide.g.storeCta" to "Connect IQ Store から入手",
    "guide.g.manualLead" to "またはサイドロードで手動インストール（例：プレビュービルド用）：",
    "guide.g.s1Title" to "1. アプリをインストール：",
    "guide.g.s1a" to "Connect IQ Store から「Pumpfoil」を入手 — またはお使いのモデル用の .prg を",
    "guide.g.s1Download" to "ここでダウンロード",
    "guide.g.s1b" to "して、次でコピーします：",
    "guide.g.s1c" to "コピー先のフォルダ：",
    "guide.g.s1d" to "ウォッチ上の。",
    "guide.g.s2Title" to "2. ウォッチでコードを生成：",
    "guide.g.s2" to "Pumpfoil を開き（開始しない）→ MENU（左中央のボタン）を長押し →「設定」→「接続」。ウォッチに6桁のコードが表示されます（スマホが近くにあるか Wi-Fi が必要）。",
    "guide.g.s3Title" to "3. ここにコードを入力：",
    "guide.g.s3" to "→「ウォッチのコードを入力」。完了 — ウォッチがアカウントに連携されました。",
    "guide.g.s4Title" to "4. データフィールドとアラーム：",
    "guide.g.s4" to "ここ pumpfoil.org の「データフィールド」（画面ごと最大3つ）と「アラーム」タブで設定 — 接続後にウォッチへ送信されます。",
    "guide.g.s5Title" to "5. 記録：",
    "guide.g.s5" to "アプリを開く →「GPS 準備完了」を待つ → START → フォイリング → START を3秒長押しで停止して保存。",
    "guide.g.s6Title" to "6. アップロード：",
    "guide.g.s6" to "次のアプリ起動時に自動的に（Wi-Fi/スマホ）、または手動で MENU → 設定 →「アップロード / 同期」。その後セッションがここに表示されます。",
    "guide.sync.title" to "セッションの後：ウォッチはいつアップロードする？",
    "guide.sync.nowTitle" to "すぐに：",
    "guide.sync.now" to "停止した瞬間にウォッチが接続されていれば（スマホが近くにある、または Wi-Fi）、アップロードは自動で始まります。",
    "guide.sync.retryTitle" to "その直後：",
    "guide.sync.retry" to "すぐに成功しない場合、ウォッチは自動で再試行します — ただし Pumpfoil アプリがウォッチで開いている間だけです。",
    "guide.sync.laterTitle" to "あとで：",
    "guide.sync.later" to "アプリが閉じている場合（文字盤表示）、セッションはウォッチに安全に保存されたままです。次にアプリを開いたときに自動送信されます — またはメニュー →「Upload / Sync」ですぐに送れます。",
    "guide.sync.note" to "何も失われません：ここにセッションが見当たらなくても、ほぼ確実にまだウォッチの中にあり、次のアプリ起動を待っているだけです。",
