    "guide.pair.autoTitle" to "自动（Apple Watch 与 Wear OS）：",
    "guide.pair.auto" to "在手机上安装应用并登录 —— 完成。手表应用会通过配对的手机自动获取连接，无需配对码。如果手表显示“链接无效”，点击“重新连接” —— 它会自动获取新的令牌。",
    "guide.pair.codeTitle" to "使用配对码（Garmin 及作为备用）：",
    "guide.pair.code" to "在手表上：“连接” → “生成配对码”，然后在此输入 6 位配对码：",
    "guide.pair.relinkTitle" to "切换或断开（Garmin）：",
    "guide.pair.relink" to "如果你在“已关联账号”下断开手表，它会在下次联通服务器时自行取消配对 —— 不再显示“已连接”，而是重新显示一个配对码。要覆盖已有的配对（换手表/账号）：在手表上“连接” → 按 ENTER 可随时生成新的配对码。旧令牌在你于此处兑换新码之前仍然有效，因此中途放弃的尝试不会改变任何东西。",
    "guide.pair.note" to "用邮箱、Google 或 Apple 登录 —— 相同的邮箱即同一个账号，无需单独关联。",
