    "guide.g.s1b" to "并用以下方式复制",
    "guide.g.s1c" to "到文件夹",
    "guide.g.s1d" to "（手表上）。",
    "guide.g.s2Title" to "2. 在手表上生成配对码：",
    "guide.g.s2" to "打开 Pumpfoil（不要启动）→ 按住 MENU（左中键）→ “设置” → “连接”。手表会显示一个 6 位配对码（需手机在附近或有 Wi-Fi）。",
    "guide.g.s3Title" to "3. 在此输入配对码：",
    "guide.g.s3" to "→ “输入手表上的配对码”。完成 —— 手表已关联到你的账号。",
