    "imp.communityIntro" to "任何人都可以创建账户。登录后,你可以看到所有用户的:",
    "imp.community1" to "显示名称和头像(如已设置;没有显示名称时记录将不显示名称)。",
    "imp.community2" to "所有检测到水翼滑行的记录:日期/时间、地点(来自 OpenStreetMap 的水域名称)、地图/GPS 轨迹(即你在哪里水翼滑行)、航段数、距离、速度、心率、泵动/滑行数值以及上传的照片。",
    "imp.community3" to "纪录和排行榜(名称、数值、地点、记录/航段/地点数量)。",
    "imp.community4" to "点赞(数量)以及“看起来是假的”/“不当内容”投票的数量。",
    "imp.communityNote" to "记录不是匿名的 — 它们通过显示名称与本人关联。未检测到水翼滑行的记录(例如纯 GPS 导入)不会出现在社区列表中。",
    "imp.ownerTitle" to "🔒 仅你自己(记录的所有者)",
    "imp.owner1" to "你记录的原始数据(单个 GPS 点、25 Hz 加速度)— 例如用于标注。",
    "imp.owner2" to "标注、裁剪、重新分析、上传/删除照片。",
    "imp.owner3" to "你的邮箱地址和账户设置 — 其他用户永远看不到。",
    "imp.owner4" to "具体是谁为某个记录投票/点赞不会显示给其他用户。",
    "imp.operatorTitle" to "🛠 仅运营者(Jan)",
    "imp.operator1" to "邮箱地址、所有原始数据、设备关联和技术性服务器日志。",
    "imp.operator2" to "密码仅以加盐哈希(PBKDF2)形式存储 — 即使是我也无法看到明文。",
    "imp.privacyTitle" to "数据删除",
    "imp.privacyText" to "所有上传的数据都会永久存储。要删除,请使用个人资料中的“删除账户”按钮(网页应用或 iOS/Android 应用)— 它会永久移除你的账户及所有记录、原始数据和照片。传输是加密的(HTTPS)。",
    "imp.googleTitle" to "Google 登录(Google 用户数据)",
    "imp.googleIntro" to "当你使用 Google 账户登录(Google Sign-In / OAuth)时,我们仅处理以下 Google 用户数据:",
    "imp.google1" to "访问的数据:你的邮箱地址、你的名字以及你的 Google 账户 ID(sub)。",
    "imp.google2" to "数据用途:仅用于创建并登录你的 Pumpfoil 账户,以及在应用中显示你的名字。",
    "imp.google3" to "不会访问其他 Google 服务或数据(没有 Google Drive、Gmail、日历等)。",
    "imp.google4" to "这些数据不会与第三方共享,不用于广告,也不用于训练 AI/ML 模型。",
    "imp.googleNote" to "对来自 Google API 信息的使用符合 Google API Services User Data Policy,包括 Limited Use 要求。",
    "imp.appleTitle" to "Apple 登录(“Sign in with Apple”)",
    "imp.appleIntro" to "当你使用 Apple 登录时,我们仅处理以下数据:",
    "imp.apple1" to "访问:你的邮箱地址(可能是 Apple 匿名化的“隐藏我的邮箱”中继地址)、你的姓名(仅在首次登录时,如果你共享)以及 Apple 用户 ID。",
    "imp.apple2" to "用途:仅用于创建并登录你的 Pumpfoil 账户。",
    "imp.apple3" to "不与第三方共享,不用于广告,不用于 AI/ML 训练。Apple 一侧的处理由 Apple 依据其隐私政策负责。",
    "imp.connTitle" to "已关联账户(Polar、COROS、Suunto)",
    "imp.connIntro" to "可选,且仅在你明确操作时,你可以关联第三方账户以导入活动:",
    "imp.conn1" to "关联时,你会被重定向到相应的提供商并在那里登录(OAuth)。我们会收到一个访问令牌以及你共享的训练/锻炼数据(包括 GPS 轨迹、时间、心率)。",
    "imp.conn2" to "这些数据仅作为你自己的记录导入,并与你的其他记录一样处理。",
    "imp.conn3" to "你可以随时在“已关联账户”中撤销关联 — 存储的令牌届时会被删除。",
    "imp.ytTitle" to "嵌入的 YouTube 视频",
    "imp.yt1" to "在主页上,我们展示来自我们 YouTube 频道的缩略图。它们通过我们自己的服务器提供 — 加载页面不会与 Google 产生任何联系,也不会设置 Cookie。",
    "imp.yt2" to "只有当你点击某个视频时,才会加载 YouTube 播放器(隐私增强模式,youtube-nocookie.com)。届时 Google/YouTube 会收到你的 IP 地址并可能设置 Cookie。点击即表示你同意此项。",
    "imp.ytNote" to "提供商:Google Ireland Ltd。更多信息见 Google 的隐私政策。",
