    "imp.title" to "Импрессум",
    "imp.whoSees" to "Конфиденциальность",
    "imp.intro" to "Это приложение — сообщество: сессии фойла видны другим. Здесь точно указано, какие данные и кому видны.",
    "imp.publicTitle" to "🌍 Публично (любой в интернете, без входа)",
    "imp.public1" to "Загруженные фото и фото профиля: файлы изображений находятся по случайной, неугадываемой ссылке. Любой, кто знает эту ссылку (например, пересланную), может открыть изображение без аккаунта. Данные EXIF/GPS в фотографиях удаляются при загрузке.",
    "imp.public2" to "Само веб-приложение и загрузка приложения для часов.",
    "imp.communityTitle" to "👥 Видно каждому зарегистрированному (сообщество)",
    "imp.communityIntro" to "Любой может создать аккаунт. После входа вы видите у всех пользователей:",
    "imp.community1" to "Отображаемое имя и фото профиля (если заданы; без отображаемого имени сессия появляется без имени).",
    "imp.community2" to "Все сессии с обнаруженным фойлингом: дата/время, спот (название водоёма из OpenStreetMap), карта/GPS-трек (то есть где вы фойлили), число заездов, дистанция, скорость, пульс, значения помпинга/скольжения и загруженные фото.",
    "imp.community3" to "Рекорды и таблицы лидеров (имя, значение, спот, число сессий/заездов/спотов).",
    "imp.community4" to "Лайки (количество) и число голосов «выглядит фейком»/«неуместно».",
    "imp.communityNote" to "Сессии не анонимны — они привязаны к человеку через отображаемое имя. Сессии без обнаруженного фойлинга (например, чистый GPS-импорт) не появляются в списках сообщества.",
    "imp.ownerTitle" to "🔒 Только вы (владелец сессии)",
    "imp.owner1" to "Необработанные данные ваших сессий (отдельные точки GPS, ускорение 25 Hz) — например, для разметки.",
    "imp.owner2" to "Метки, обрезка, повторный анализ, загрузка/удаление фото.",
    "imp.owner3" to "Ваш адрес электронной почты и настройки аккаунта — никогда не видны другим пользователям.",
    "imp.owner4" to "Кто именно голосовал/ставил лайк сессии, не показывается другим пользователям.",
    "imp.operatorTitle" to "🛠 Только оператор (Jan)",
    "imp.operator1" to "Адреса электронной почты, все необработанные данные, привязки устройств и технические журналы сервера.",
    "imp.operator2" to "Пароли хранятся только как хеш с солью (PBKDF2) — даже я не вижу их в открытом виде.",
    "imp.privacyTitle" to "Удаление данных",
    "imp.privacyText" to "Все загруженные данные хранятся постоянно. Чтобы их удалить, используйте кнопку «Удалить аккаунт» в профиле (веб-приложение или приложение iOS/Android) — она навсегда удаляет ваш аккаунт со всеми сессиями, необработанными данными и фотографиями. Передача шифруется (HTTPS).",
    "imp.googleTitle" to "Вход через Google (пользовательские данные Google)",
    "imp.googleIntro" to "Когда вы входите через свой аккаунт Google (Google Sign-In / OAuth), мы обрабатываем только следующие пользовательские данные Google:",
    "imp.google1" to "Данные, к которым есть доступ: ваш адрес электронной почты, ваше имя и идентификатор вашего аккаунта Google (sub).",
    "imp.google2" to "Использование данных: исключительно для создания и входа в ваш аккаунт Pumpfoil и отображения вашего имени в приложении.",
    "imp.google3" to "Доступа к другим сервисам или данным Google нет (нет Google Drive, Gmail, Календаря и т. д.).",
    "imp.google4" to "Эти данные не передаются третьим лицам, не используются для рекламы и не используются для обучения моделей ИИ/ML.",
    "imp.googleNote" to "Использование информации из Google API соответствует Google API Services User Data Policy, включая требования Limited Use.",
    "imp.appleTitle" to "Вход через Apple («Sign in with Apple»)",
    "imp.appleIntro" to "Когда вы входите через Apple, мы обрабатываем только следующие данные:",
    "imp.apple1" to "Доступ: ваш адрес электронной почты (возможно, анонимизированный ретранслирующий адрес Apple «Скрыть e-mail»), ваше имя (только один раз при первом входе, если вы им поделитесь) и идентификатор пользователя Apple.",
    "imp.apple2" to "Использование: исключительно для создания и входа в ваш аккаунт Pumpfoil.",
    "imp.apple3" to "Без передачи третьим лицам, без рекламы, без обучения ИИ/ML. Apple отвечает за обработку на своей стороне в соответствии со своей политикой конфиденциальности.",
    "imp.connTitle" to "Связанные аккаунты (Polar, COROS, Suunto)",
    "imp.connIntro" to "По желанию и только по вашему явному действию вы можете связать сторонний аккаунт для импорта активностей:",
    "imp.conn1" to "При связывании вы перенаправляетесь к соответствующему провайдеру и входите там (OAuth). Мы получаем токен доступа и данные тренировок/воркаутов, которыми вы делитесь (включая GPS-трек, время, пульс).",
    "imp.conn2" to "Эти данные импортируются только как ваши собственные сессии и обрабатываются как остальные ваши сессии.",
    "imp.conn3" to "Вы можете отозвать связь в любой момент в разделе «Связанные аккаунты» — сохранённый токен затем удаляется.",
    "imp.ytTitle" to "Встроенные видео YouTube",
    "imp.yt1" to "На главной странице мы показываем миниатюры с нашего YouTube-канала. Они отдаются с нашего собственного сервера — загрузка страницы не создаёт контакта с Google и не устанавливает cookie.",
    "imp.yt2" to "Только когда вы нажимаете на видео, загружается плеер YouTube (режим повышенной конфиденциальности, youtube-nocookie.com). Google/YouTube тогда получает ваш IP-адрес и может устанавливать cookie. Нажатием вы соглашаетесь с этим.",
    "imp.ytNote" to "Провайдер: Google Ireland Ltd. Подробнее — в политике конфиденциальности Google.",
