    "imp.title" to "Impresum",
    "imp.whoSees" to "Privasi",
    "imp.intro" to "Aplikasi ini adalah komunitas: sesi foil dibagikan dengan orang lain. Berikut penjelasan persis data mana yang terlihat oleh siapa.",
    "imp.publicTitle" to "🌍 Publik (siapa pun di internet, tanpa login)",
    "imp.public1" to "Foto yang diunggah dan foto profil: berkas gambar berada di tautan acak yang tidak bisa ditebak. Siapa pun yang tahu tautan itu (mis. diteruskan) dapat membuka gambar tanpa akun. Data EXIF/GPS pada foto dihapus saat diunggah.",
    "imp.public2" to "Aplikasi web itu sendiri dan unduhan aplikasi jam.",
    "imp.communityTitle" to "👥 Terlihat oleh setiap orang yang terdaftar (komunitas)",
    "imp.communityIntro" to "Siapa pun dapat membuat akun. Setelah masuk, Anda melihat dari semua pengguna:",
    "imp.community1" to "Nama tampilan dan foto profil (jika diatur; tanpa nama tampilan, sesi muncul tanpa nama).",
    "imp.community2" to "Semua sesi dengan foiling terdeteksi: tanggal/waktu, spot (nama perairan dari OpenStreetMap), peta/jalur GPS (yaitu di mana Anda ber-foil), jumlah run, jarak, kecepatan, detak jantung, nilai pump/luncuran, dan foto yang diunggah.",
    "imp.community3" to "Rekor dan papan peringkat (nama, nilai, spot, jumlah sesi/run/spot).",
    "imp.community4" to "Suka (jumlah) dan jumlah suara “terlihat palsu”/“tidak pantas”.",
    "imp.communityNote" to "Sesi tidak anonim — terhubung ke orang melalui nama tampilan. Sesi tanpa foiling terdeteksi (mis. impor GPS saja) tidak muncul di daftar komunitas.",
    "imp.ownerTitle" to "🔒 Hanya Anda (pemilik sesi)",
    "imp.owner1" to "Data mentah sesi Anda (titik GPS individual, akselerasi 25 Hz) — mis. untuk pelabelan.",
    "imp.owner2" to "Label, pemotongan, analisis ulang, unggah/hapus foto.",
    "imp.owner3" to "Alamat email dan pengaturan akun Anda — tidak pernah terlihat oleh pengguna lain.",
    "imp.owner4" to "Siapa persisnya yang memilih/menyukai sebuah sesi tidak ditampilkan ke pengguna lain.",
    "imp.operatorTitle" to "🛠 Hanya operator (Jan)",
    "imp.operator1" to "Alamat email, semua data mentah, tautan perangkat, dan log server teknis.",
    "imp.operator2" to "Kata sandi hanya disimpan sebagai hash ber-salt (PBKDF2) — bahkan saya tidak bisa melihatnya dalam teks biasa.",
    "imp.privacyTitle" to "Penghapusan data",
    "imp.privacyText" to "Semua data yang diunggah disimpan secara permanen. Untuk menghapusnya, gunakan tombol “Hapus akun” di profil Anda (aplikasi web atau aplikasi iOS/Android) — tombol itu menghapus akun Anda secara permanen beserta semua sesi, data mentah, dan foto. Transmisi dienkripsi (HTTPS).",
    "imp.googleTitle" to "Login Google (data pengguna Google)",
    "imp.googleIntro" to "Saat Anda masuk dengan akun Google (Google Sign-In / OAuth), kami hanya memproses data pengguna Google berikut:",
    "imp.google1" to "Data yang diakses: alamat email Anda, nama depan Anda, dan ID akun Google Anda (sub).",
    "imp.google2" to "Penggunaan data: semata-mata untuk membuat dan masuk ke akun Pumpfoil Anda serta menampilkan nama depan Anda di aplikasi.",
    "imp.google3" to "Tidak ada akses ke layanan atau data Google lainnya (tidak ada Google Drive, Gmail, Kalender, dll.).",
    "imp.google4" to "Data ini tidak dibagikan ke pihak ketiga, tidak digunakan untuk iklan, dan tidak digunakan untuk melatih model AI/ML.",
    "imp.googleNote" to "Penggunaan informasi dari Google API mematuhi Google API Services User Data Policy, termasuk persyaratan Limited Use.",
    "imp.appleTitle" to "Login Apple (“Sign in with Apple”)",
    "imp.appleIntro" to "Saat Anda masuk dengan Apple, kami hanya memproses data berikut:",
    "imp.apple1" to "Akses: alamat email Anda (mungkin alamat relay “Sembunyikan Email Saya” anonim dari Apple), nama Anda (hanya sekali saat login pertama, jika Anda membagikannya), dan ID pengguna Apple.",
    "imp.apple2" to "Penggunaan: semata-mata untuk membuat dan masuk ke akun Pumpfoil Anda.",
    "imp.apple3" to "Tidak ada berbagi ke pihak ketiga, tidak ada iklan, tidak ada pelatihan AI/ML. Apple bertanggung jawab atas pemrosesan di sisi Apple sesuai kebijakan privasi mereka.",
    "imp.connTitle" to "Akun tertaut (Polar, COROS, Suunto)",
    "imp.connIntro" to "Secara opsional, dan hanya atas tindakan eksplisit Anda, Anda dapat menautkan akun pihak ketiga untuk mengimpor aktivitas:",
    "imp.conn1" to "Saat menautkan, Anda diarahkan ke penyedia terkait dan masuk di sana (OAuth). Kami menerima token akses dan data latihan/workout yang Anda bagikan (termasuk jalur GPS, waktu, detak jantung).",
    "imp.conn2" to "Data ini diimpor hanya sebagai sesi milik Anda sendiri dan diperlakukan seperti sesi Anda yang lain.",
    "imp.conn3" to "Anda dapat mencabut tautan kapan saja di “Akun tertaut” — token yang tersimpan lalu dihapus.",
    "imp.ytTitle" to "Video YouTube tersemat",
    "imp.yt1" to "Di halaman beranda kami menampilkan thumbnail dari kanal YouTube kami. Thumbnail itu disajikan melalui server kami sendiri — memuat halaman tidak membuat kontak dengan Google dan tidak menyetel cookie.",
    "imp.yt2" to "Hanya saat Anda mengeklik video, pemutar YouTube (mode privasi yang ditingkatkan, youtube-nocookie.com) dimuat. Google/YouTube kemudian menerima alamat IP Anda dan dapat menyetel cookie. Dengan mengeklik, Anda menyetujui hal ini.",
    "imp.ytNote" to "Penyedia: Google Ireland Ltd. Selengkapnya di kebijakan privasi Google.",
