    "nav.imprint" to "Kontakt og personvern",
    "imp.title" to "Kontakt og juridisk info",
    "imp.whoSees" to "Personvern",
    "imp.intro" to "Denne appen er et fellesskap: foil-økter deles med andre. Her ser du nøyaktig hvilke data som er synlige for hvem.",
    "imp.publicTitle" to "🌍 Offentlig (alle på internett, uten innlogging)",
    "imp.public1" to "<b>Opplastede bilder</b> og <b>profilbilder</b>: bildefilene ligger under en tilfeldig lenke som ikke kan gjettes. Alle som kjenner lenken (f.eks. videresendt) kan åpne bildet uten konto. EXIF-/GPS-data i bilder fjernes ved opplasting.",
    "imp.public2" to "Selve web-appen og nedlastingen av klokke-appen.",
    "imp.communityTitle" to "👥 Synlig for alle registrerte (fellesskapet)",
    "imp.communityIntro" to "Alle kan opprette en konto. Når du er logget inn, ser du fra <b>alle</b> brukere:",
    "imp.community1" to "<b>Visningsnavn</b> og <b>profilbilde</b> (hvis satt; uten visningsnavn vises økten uten navn).",
    "imp.community2" to "<b>Alle økter med registrert foiling</b>: dato/klokkeslett, <b>spot</b> (navn på vannet fra OpenStreetMap), <b>kartet/GPS-sporet</b> (altså <u>hvor</u> du foilet), antall runs, distanse, fart, puls, pump-/glideverdier og de opplastede <b>bildene</b>.",
    "imp.community3" to "<b>Rekorder &amp; topplister</b> (navn, verdi, spot, antall økter/runs/spots).",
    "imp.community4" to "<b>Likes</b> (antall) og <b>antallet</b> «ser falskt ut»/«upassende»-stemmer.",
    "imp.communityNote" to "Økter er <b>ikke anonyme</b> — de er knyttet til personen via visningsnavnet. Du kan slette hver enkelt økt når som helst; bare økter du <b>skjuler</b> vises ikke i fellesskapslistene (GPS-only-økter vises også).",
    "imp.ownerTitle" to "🔒 Bare du (eieren av økten)",
    "imp.owner1" to "<b>Rådata</b> fra øktene dine (enkelte GPS-punkter, 25 Hz akselerasjon) — f.eks. til merking.",
    "imp.owner2" to "Merking, trimming, ny analyse, opplasting/sletting av bilder.",
    "imp.owner3" to "<b>E-postadressen</b> din og kontoinnstillinger — aldri synlig for andre brukere.",
    "imp.owner4" to "Hvem som konkret har stemt eller likt en økt, vises ikke for andre brukere.",
    "imp.operatorTitle" to "🛠 Bare operatøren (Jan)",
    "imp.operator1" to "E-postadresser, alle rådata, enhetskoblinger og tekniske serverlogger.",
    "imp.operator2" to "Passord lagres bare som en saltet hash (PBKDF2) — selv jeg kan ikke se dem i klartekst.",
    "imp.privacyTitle" to "Sletting av data",
    "imp.privacyText" to "Alle opplastede data lagres permanent. For å slette dem bruker du knappen «Slett konto» i profilen din (web-appen eller iOS-/Android-appen) — den fjerner kontoen din permanent med alle økter, rådata og bilder. Overføringen er kryptert (HTTPS).",
    "imp.googleTitle" to "Google-innlogging (Google-brukerdata)",
    "imp.googleIntro" to "Når du logger inn med Google-kontoen din (Google Sign-In / OAuth), behandler vi bare disse Google-brukerdataene:",
    "imp.google1" to "<b>Data vi får tilgang til:</b> e-postadressen din, fornavnet ditt og Google-konto-ID-en din (sub).",
    "imp.google2" to "<b>Bruk av data:</b> kun for å opprette og logge inn på Pumpfoil-kontoen din og for å vise fornavnet ditt i appen.",
    "imp.google3" to "Det er <b>ingen tilgang</b> til andre Google-tjenester eller -data (ingen Google Drive, Gmail, Kalender osv.).",
    "imp.google4" to "Disse dataene <b>deles ikke med tredjeparter</b>, brukes ikke til reklame og brukes ikke til å trene AI/ML-modeller.",
    "imp.googleNote" to "Bruk av informasjon fra Google-API-er følger <a href=\"https://developers.google.com/terms/api-services-user-data-policy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">Google API Services User Data Policy</a>, inkludert kravene om begrenset bruk (Limited Use).",
    "imp.appleTitle" to "Apple-innlogging (“Logg på med Apple”)",
    "imp.appleIntro" to "Når du logger inn med Apple, behandler vi bare disse dataene:",
    "imp.apple1" to "<b>Tilgang:</b> e-postadressen din (eventuelt Apples anonymiserte “Skjul e-postadresse”-adresse), navnet ditt (bare én gang ved første innlogging, hvis du deler det) og Apple-bruker-ID-en.",
    "imp.apple2" to "<b>Bruk:</b> kun for å opprette og logge inn på Pumpfoil-kontoen din.",
    "imp.apple3" to "Ingen deling med tredjeparter, ingen reklame, ingen AI/ML-trening. Apple er ansvarlig for behandlingen på Apples side i henhold til deres personvernerklæring.",
    "imp.connTitle" to "Tilknyttede kontoer (Polar, COROS, Suunto)",
    "imp.connIntro" to "Valgfritt, og bare når du selv gjør det, kan du knytte til en tredjepartskonto for å importere aktiviteter:",
    "imp.conn1" to "Ved tilknytning blir du sendt til den aktuelle leverandøren og logger inn der (OAuth). Vi får et tilgangstoken og de trenings-/aktivitetsdataene du deler (inkludert GPS-spor, tid, puls).",
    "imp.conn2" to "Disse dataene importeres kun som dine egne økter og behandles som de øvrige øktene dine.",
    "imp.conn3" to "Du kan oppheve tilknytningen når som helst under “Tilknyttede kontoer” — det lagrede tokenet slettes da.",
    "imp.ytTitle" to "Innebygde YouTube-videoer",
    "imp.yt1" to "På hjemmesiden viser vi miniatyrbilder fra YouTube-kanalen vår. De leveres via <b>vår egen server</b> — å laste siden gir <b>ingen</b> kontakt med Google og setter <b>ingen</b> cookies.",
    "imp.yt2" to "Først når du <b>klikker</b> på en video, lastes YouTube-spilleren (personvernmodus, youtube-nocookie.com). Google/YouTube får da IP-adressen din og kan sette cookies. Ved å klikke samtykker du til dette.",
    "imp.ytNote" to "Leverandør: Google Ireland Ltd. Mer i <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-brand-400 hover:underline\">Googles personvernerklæring</a>.",
