    "garmin.title" to "Połącz zegarek Garmin",
    "garmin.sub" to "Wpisz albo wygeneruj kod",
    "guide.howto" to "Jak skonfigurować zegarek",
    "guide.pair.title" to "Połącz zegarek ze swoim kontem",
    "guide.pair.intro" to "Możesz nagrywać bez łączenia — sesje zapisują się lokalnie i wysyłają automatycznie później. Aby przypisać je do konta, są dwie drogi:",
    "guide.pair.autoTitle" to "Automatycznie (Apple Watch i Wear OS):",
    "guide.pair.auto" to "Zainstaluj aplikację w telefonie i zaloguj się — gotowe. Aplikacja na zegarku dostaje połączenie automatycznie przez sparowany telefon, bez kodu. Jeśli zegarek pokazuje „Połączenie nieważne”, dotknij „Połącz ponownie” — pobierze świeży token automatycznie.",
    "guide.pair.codeTitle" to "Kodem (Garmin i jako rozwiązanie zapasowe):",
    "guide.pair.code" to "Na zegarku: „Połącz” → „Wygeneruj kod parowania”, potem wpisz tutaj 6-znakowy kod:",
    "guide.pair.relinkTitle" to "Zmiana albo rozłączenie (Garmin):",
    "guide.pair.relink" to "Jeśli rozłączysz zegarek w „Połączonych kontach”, sam porzuci parowanie przy następnym kontakcie z serwerem — zamiast „Połączono” znów pokaże kod. Aby nadpisać istniejące parowanie (inny zegarek/konto): na zegarku „Połącz” → ENTER generuje świeży kod w każdej chwili. Stary token pozostaje ważny, dopóki nie wpiszesz tutaj nowego kodu, więc przerwana próba niczego nie zmienia.",
    "guide.pair.note" to "Zaloguj się e-mailem, przez Google albo Apple — ten sam e-mail oznacza to samo konto, osobne łączenie nie jest potrzebne.",
    "guide.connect" to "„Połącz”",
    "guide.garminSub" to "Fenix, Forerunner, Epix, Instinct …",
    "guide.g.storeLead" to "Już w sklepie — najprościej zainstalować bezpośrednio:",
    "guide.g.storeCta" to "Pobierz z Connect IQ Store",
    "guide.g.manualLead" to "Albo zainstaluj ręcznie przez sideload (np. wersje testowe):",
    "guide.g.s1Title" to "1. Zainstaluj aplikację:",
    "guide.g.s1a" to "pobierz „Pumpfoil” z Connect IQ Store — albo plik .prg dla swojego modelu",
    "guide.g.s1Download" to "pobierz tutaj",
    "guide.g.s1b" to "i skopiuj go za pomocą",
    "guide.g.s1c" to "do folderu",
    "guide.g.s1d" to "na zegarku.",
    "guide.g.s2Title" to "2. Wygeneruj kod na zegarku:",
    "guide.g.s2" to "otwórz Pumpfoil (nie startuj) → przytrzymaj MENU (środkowy lewy przycisk) → „Ustawienia” → „Połącz”. Zegarek pokaże 6-znakowy kod (wymagany telefon w pobliżu albo Wi-Fi).",
    "guide.g.s3Title" to "3. Wpisz kod tutaj:",
    "guide.g.s3" to "→ „Wpisz kod z zegarka”. Gotowe — zegarek jest powiązany z Twoim kontem.",
    "guide.g.s4Title" to "4. Pola danych i alarm:",
    "guide.g.s4" to "ustawiasz tutaj, na pumpfoil.org, w zakładkach „Pola danych” (do 3 na ekran) i „Alarm” — trafiają na zegarek po połączeniu.",
    "guide.g.s5Title" to "5. Nagrywanie:",
    "guide.g.s5" to "otwórz aplikację → poczekaj na „GPS gotowy” → START → jedź na foilu → przytrzymaj START 3 s, aby zatrzymać i zapisać.",
    "guide.g.s6Title" to "6. Wysyłka:",
    "guide.g.s6" to "automatycznie przy następnym starcie aplikacji (Wi-Fi/telefon) albo ręcznie MENU → Ustawienia → „Wysyłka / Sync”. Sesja pojawi się wtedy tutaj.",
    "guide.sync.title" to "Po sesji: kiedy zegarek wysyła dane?",
    "guide.sync.nowTitle" to "Od razu:",
    "guide.sync.now" to "Jeśli w chwili zatrzymania zegarek jest połączony (telefon w pobliżu albo Wi-Fi), wysyłka rusza sama.",
    "guide.sync.retryTitle" to "Chwilę później:",
    "guide.sync.retry" to "Jeśli nie uda się od razu, zegarek ponawia próby automatycznie — ale tylko dopóki aplikacja Pumpfoil pozostaje na nim otwarta.",
    "guide.sync.laterTitle" to "Później:",
    "guide.sync.later" to "Jeśli aplikacja jest zamknięta (zegarek pokazuje tarczę), sesja pozostaje bezpiecznie zapisana na zegarku. Wyśle się automatycznie przy następnym otwarciu aplikacji — albo od razu przez menu → „Wysyłka / Sync”.",
    "guide.sync.note" to "Nic nie ginie: jeśli brakuje tu sesji, prawie zawsze jest jeszcze na zegarku i czeka na następne uruchomienie aplikacji.",
    "garmin.installTitle" to "Najpierw: wgraj aplikację na zegarek",
    "garmin.installHelp" to "Aplikacji na zegarek NIE MA w Sklepie Play — w Garminie pochodzi ze sklepu Connect IQ. Dotknij „Otwórz Connect IQ Store” i zainstaluj ją tam (aplikacja Garmin Connect w telefonie prześle ją na zegarek). Dopiero potem kroki poniżej.",
