    "imp.title" to "Impressum",
    "imp.whoSees" to "Prywatność",
    "imp.intro" to "Ta aplikacja to społeczność: sesje foilowe są udostępniane innym. Poniżej dokładnie, które dane są dla kogo widoczne.",
    "imp.publicTitle" to "🌍 Publicznie (każdy w internecie, bez logowania)",
    "imp.public1" to "<b>Wysłane zdjęcia</b> i <b>zdjęcia profilowe</b>: pliki obrazów leżą pod losowym, nieodgadywalnym linkiem. Każdy, kto zna ten link (np. przesłany dalej), może otworzyć obraz bez konta. Dane EXIF/GPS w zdjęciach są usuwane przy wysyłaniu.",
    "imp.public2" to "Sama aplikacja webowa i pobranie aplikacji na zegarek.",
    "imp.communityTitle" to "👥 Widoczne dla każdej zarejestrowanej osoby (społeczność)",
    "imp.communityIntro" to "Konto może założyć każdy. Po zalogowaniu widzisz u <b>wszystkich</b> użytkowników:",
    "imp.community1" to "<b>Nazwę wyświetlaną</b> i <b>zdjęcie profilowe</b> (jeśli ustawione; bez nazwy wyświetlanej sesja pojawia się bez nazwy).",
    "imp.community2" to "<b>Wszystkie sesje z wykrytym foilingiem</b>: datę/godzinę, <b>spot</b> (nazwa akwenu z OpenStreetMap), <b>mapę/ślad GPS</b> (czyli <u>gdzie</u> foilowałeś), liczbę przejazdów, dystans, prędkość, tętno, wartości pomp/szybowania oraz wysłane <b>zdjęcia</b>.",
    "imp.community3" to "<b>Rekordy i rankingi</b> (nazwa, wartość, spot, liczba sesji/przejazdów/spotów).",
    "imp.community4" to "<b>Polubienia</b> (liczba) oraz <b>liczbę</b> głosów „wygląda na fejk”/„nieodpowiednie”.",
    "imp.communityNote" to "Sesje <b>nie są anonimowe</b> — są powiązane z osobą przez jej nazwę wyświetlaną. Każdą sesję możesz w każdej chwili pojedynczo usunąć; tylko sesje, które <b>ukryjesz</b>, nie pojawiają się na listach społeczności (sesje tylko z GPS też są pokazywane).",
    "imp.ownerTitle" to "🔒 Tylko Ty (właściciel sesji)",
    "imp.owner1" to "<b>Surowe dane</b> Twoich sesji (pojedyncze punkty GPS, przyspieszenie 25 Hz) — np. do etykietowania.",
    "imp.owner2" to "Etykiety, przycinanie, ponowna analiza, wysyłanie/usuwanie zdjęć.",
    "imp.owner3" to "Twój <b>adres e-mail</b> i ustawienia konta — nigdy widoczne dla innych użytkowników.",
    "imp.owner4" to "Kto konkretnie zagłosował/polubił sesję, nie jest pokazywane innym użytkownikom.",
    "imp.operatorTitle" to "🛠 Tylko operator (Jan)",
    "imp.operator1" to "Adresy e-mail, wszystkie surowe dane, powiązania urządzeń i techniczne logi serwera.",
    "imp.operator2" to "Hasła są przechowywane wyłącznie jako solony skrót (PBKDF2) — nawet ja nie widzę ich w postaci jawnej.",
    "imp.privacyTitle" to "Usuwanie danych",
    "imp.privacyText" to "Wszystkie wysłane dane są przechowywane trwale. Aby je usunąć, użyj przycisku „Usuń konto” w swoim profilu (aplikacja webowa albo iOS/Android) — trwale usuwa on Twoje konto ze wszystkimi sesjami, surowymi danymi i zdjęciami. Przesyłanie jest szyfrowane (HTTPS).",
    "imp.googleTitle" to "Logowanie Google (dane użytkownika Google)",
    "imp.googleIntro" to "Gdy logujesz się swoim kontem Google (Google Sign-In / OAuth), przetwarzamy wyłącznie następujące dane użytkownika Google:",
    "imp.google1" to "<b>Dane, do których mamy dostęp:</b> Twój adres e-mail, Twoje imię oraz identyfikator konta Google (sub).",
    "imp.google2" to "<b>Zastosowanie danych:</b> wyłącznie do założenia konta Pumpfoil i logowania się do niego oraz do pokazania Twojego imienia w aplikacji.",
    "imp.google3" to "<b>Nie ma dostępu</b> do innych usług ani danych Google (żadnego Google Drive, Gmaila, Kalendarza itd.).",
    "imp.google4" to "Te dane <b>nie są przekazywane osobom trzecim</b>, nie służą do reklam ani do trenowania modeli AI/ML.",
    "imp.googleNote" to "Korzystanie z informacji z Google API jest zgodne z <a href=\\\\\\\"https://developers.google.com/terms/api-services-user-data-policy\\\\\\\" target=\\\\\\\"_blank\\\\\\\" rel=\\\\\\\"noopener noreferrer\\\\\\\" class=\\\\\\\"text-brand-400 hover:underline\\\\\\\">Google API Services User Data Policy</a>, w tym z wymogami Limited Use.",
    "imp.appleTitle" to "Logowanie Apple („Sign in with Apple”)",
    "imp.appleIntro" to "Gdy logujesz się przez Apple, przetwarzamy wyłącznie następujące dane:",
    "imp.apple1" to "<b>Dostęp:</b> Twój adres e-mail (ewentualnie zanonimizowany adres przekierowujący Apple „Hide My Email”), Twoje imię (tylko raz, przy pierwszym logowaniu, jeśli je udostępnisz) oraz identyfikator użytkownika Apple.",
    "imp.apple2" to "<b>Zastosowanie:</b> wyłącznie do założenia konta Pumpfoil i logowania się do niego.",
    "imp.apple3" to "Brak przekazywania osobom trzecim, brak reklam, brak trenowania AI/ML. Za przetwarzanie po stronie Apple odpowiada Apple, zgodnie ze swoją polityką prywatności.",
    "imp.connTitle" to "Połączone konta (Polar, COROS, Suunto)",
    "imp.connIntro" to "Opcjonalnie i wyłącznie na Twoje wyraźne działanie możesz połączyć konto innej usługi, aby importować aktywności:",
    "imp.conn1" to "Przy łączeniu zostajesz przekierowany do danego dostawcy i logujesz się u niego (OAuth). Otrzymujemy token dostępu oraz udostępnione przez Ciebie dane treningów (w tym ślad GPS, czas, tętno).",
    "imp.conn2" to "Te dane są importowane wyłącznie jako Twoje własne sesje i traktowane jak pozostałe Twoje sesje.",
    "imp.conn3" to "Połączenie możesz w każdej chwili cofnąć w „Połączonych kontach” — zapisany token zostaje wtedy usunięty.",
    "imp.ytTitle" to "Osadzone wideo z YouTube",
    "imp.yt1" to "Na stronie głównej pokazujemy miniatury z naszego kanału YouTube. Są serwowane przez <b>nasz własny serwer</b> — samo wczytanie strony <b>nie</b> nawiązuje kontaktu z Google i <b>nie</b> ustawia żadnych ciasteczek.",
    "imp.yt2" to "Dopiero gdy <b>klikniesz</b> wideo, ładowany jest odtwarzacz YouTube (tryb rozszerzonej prywatności, youtube-nocookie.com). Google/YouTube otrzymuje wtedy Twój adres IP i może ustawić ciasteczka. Klikając, wyrażasz na to zgodę.",
    "imp.ytNote" to "Dostawca: Google Ireland Ltd. Więcej w <a href=\\\\\\\"https://policies.google.com/privacy\\\\\\\" target=\\\\\\\"_blank\\\\\\\" rel=\\\\\\\"noopener noreferrer\\\\\\\" class=\\\\\\\"text-brand-400 hover:underline\\\\\\\">polityce prywatności Google</a>.",
